<script setup>
import { inject, ref, onMounted, watch, computed } from 'vue'
import { useRoute } from 'vue-router'
import StatusChip from '../components/StatusChip.vue'
import { messages } from '../services/repository'
const repo=inject('repository'),notify=inject('notify'),route=useRoute(),event=ref(null),surgery=ref(null),error=ref(''),loading=ref(true)
async function load(){loading.value=true;error.value='';try{event.value=await repo.getAlert(route.params.id);const c=await repo.getCatalog();surgery.value=c.surgeries.find(s=>String(s.id)===String(event.value?.surgeryId))}catch(e){error.value=e.message}finally{loading.value=false}}
async function update(status){try{await repo.setMessageStatus(event.value.id,status);event.value=await repo.getAlert(event.value.id);notify('消息状态已更新')}catch(e){error.value=e.message}}
const patient=computed(()=>event.value?{'患者':event.value.patientName,'患者 ID':event.value.patientId,'手术编号':event.value.surgeryNo,'手术名称':event.value.surgeryName,'科室 / 医疗组':event.value.dept+' / '+event.value.group,'手术间':event.value.roomName,'主刀医师':event.value.surgeon,'手术级别':surgery.value?.surgeryLevel}:{} )
watch(()=>route.params.id,load);onMounted(load)
</script>
<template>
<div class="page-heading"><div><VBtn to="/alerts" variant="text" prepend-icon="tabler-arrow-left" size="small" class="mb-3">返回告警中心</VBtn><h1>告警详情</h1><p>核对患者、触发证据与响应信息，追溯事件来源。</p></div></div>
<VAlert v-if="error" type="error" variant="tonal" class="mb-6">{{error}}<VBtn variant="text" @click="load">重试</VBtn></VAlert><VProgressLinear v-if="loading" indeterminate/>
<template v-else-if="event"><VCard class="mb-6"><div class="section-head"><div><div class="action-row mb-3"><StatusChip :value="event.level"/><VChip color="primary" label variant="tonal">{{event.sourceLabel}}</VChip><span class="caption muted">{{event.id}}</span></div><h2 style="font-size:var(--font-size-xl)">{{event.indicator}}</h2><p>{{event.triggerTime}} · {{event.phaseLabel}} · {{event.decisionGoal}}</p></div><VMenu><template #activator="{props}"><VBtn v-bind="props" variant="tonal" append-icon="tabler-chevron-down">{{messages[event.messageStatus]}}</VBtn></template><VList><VListItem v-for="(title,key) in messages" :key="key" :title="title" @click="update(key)"/></VList></VMenu></div></VCard>
<div class="detail-grid"><div class="stack"><VCard title="患者与手术"><VCardText><dl class="data-grid"><div v-for="(value,label) in patient" :key="label"><dt>{{label}}</dt><dd>{{value||'—'}}</dd></div></dl></VCardText></VCard>
<VCard title="触发证据"><VCardText><dl class="data-grid"><div><dt>规则编号</dt><dd>{{event.ruleId}}</dd></div><div><dt>触发时间</dt><dd>{{event.triggerTime}}</dd></div></dl><div class="evidence-box"><h3>{{event.indicator}}</h3><p>{{event.triggerEvidence||'当前数据源未提供数值证据'}}</p><p class="caption muted mt-3">{{event.desc||'未设置补充说明'}}</p></div><div v-if="event.threshold" class="mt-5"><p class="caption muted mb-2">判定依据</p><p>{{event.threshold}}</p></div><VTable v-if="event.evidenceItems?.length" class="mt-5"><thead><tr><th>证据项</th><th>数值 / 说明</th><th>来源</th><th>证据时间</th></tr></thead><tbody><tr v-for="(e,i) in event.evidenceItems" :key="i"><td>{{e.label}}</td><td>{{e.value}}</td><td>{{e.source}}</td><td class="date-cell">{{e.time||'—'}}</td></tr></tbody></VTable></VCardText></VCard></div>
<div class="stack" style="align-content:start"><VCard title="响应与追溯"><VCardText><dl class="data-grid" style="grid-template-columns:1fr"><div><dt>处置状态</dt><dd><StatusChip :value="event.responseStatus" kind="response"/></dd></div><div><dt>告警接收角色</dt><dd>{{event.recipients?.join('、')||'—'}}</dd></div><div><dt>响应时限</dt><dd>{{event.responseSla||'—'}}</dd></div><div><dt>数据来源</dt><dd>{{event.sourceSystem||'—'}}</dd></div><div><dt>升级路径</dt><dd>{{event.escalationPolicy||event.escalation||'—'}}</dd></div><div><dt>关联生命体征</dt><dd>{{surgery?.vitalSignsCount?`${surgery.vitalSignsCount} 条`:'—'}}</dd></div></dl></VCardText></VCard>
<VAlert variant="tonal" color="primary" icon="tabler-info-circle"><div class="caption"><strong>{{event.ruleId==='MANUAL'?'人工填报 · 模板快照':'模拟监管事件'}}</strong><p class="mt-2" v-if="event.ruleId==='MANUAL'">填报时间：{{new Date(event.reportedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}<br>{{event.notificationStatus}}。历史记录保留填报时的模板内容。</p><p v-else class="mt-2">阈值上线前须经医院手术质量安全委员会审定。此页面展示模拟证据与处置信息。</p></div></VAlert></div></div>
</template><VCard v-else-if="!error" class="empty"><VIcon icon="tabler-file-search" size="40"/><h3>未找到这条告警</h3><p>记录可能已重置，请返回列表重新选择。</p><VBtn to="/alerts">返回告警中心</VBtn></VCard>
</template>
